from pathlib import Path
import json,hashlib,datetime
R=Path(__file__).resolve().parents[5];D=Path(__file__).resolve().parent;C=Path('/tmp/medina-source-cache/endocrinologie/E30')
assert not (D/'source-binding.json').exists(),'Final evidence sealed; never refresh automatically.'
rows=[]
def add(i,url,title,pub,version,file,section,pop,limits,note,level='section'):
 p=Path(file);p=p if p.is_absolute() else C/p
 assert p.is_file(),p
 rows.append(dict(id=i,url=url,titre=title,editeur=pub,version_annee=version,date_consultation='2026-11-02',section_page=section,population=pop,limites=limits,cache_external=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),lecteur='sol_endocrinologie',read_level=level,passage_paraphrase=note))
add('S1','https://dam-api.bfs.admin.ch/hub/api/dam/assets/32686265/master','CIM-10-GM E30 et subdivisions','OFS Suisse','2024',R/'nosology/fragments/S05.json','Toutes entrées locales E30, E30.0, E30.1, E30.8, E30.9','Classification suisse','Libellés locaux 2024 ; aucune certification administrative 2026.','E30.0 est retardée, E30.1 précoce, E30.8 autre et E30.9 sans précision ; diagnostic étiologique et code sont distingués.')
add('S2','https://klassifikationen.bfarm.de/icd-10-gm/kode-suche/htmlgm2024/block-e20-e35.htm','Notes CIM-10-GM E30 et E22.8','BfArM Allemagne','2024','bfarm2024.html','Entrées E30.0–E30.9, inclusions/exclusions ; E22.8','Classification allemande de référence','Notes allemandes confrontées aux libellés suisses, pas règles suisses détaillées certifiées 2026.','La forme centrale est exclue de E30.1 vers E22.8 ; hyperplasie surrénale et McCune-Albright sont ailleurs. E30.8 inclut thélarche et pubarche prématurées.')
add('S3','https://www.chuv.ch/fr/dedop/dedop-home/patients-et-famille/endocrinologie/troubles-de-la-puberte','Troubles de la puberté','CHUV Suisse','Page consultée 2026-11-02','chuv-puberty.html','Page clinique patient entière','Enfants suisses et familles','Information aux patients, sans seuils de laboratoire ni protocole de prescription.','L’examen, la vitesse de croissance, l’âge osseux et des dosages orientent la cause. Freiner ou induire n’est pas systématiquement nécessaire ; le suivi dépend du cas.')
add('S4','https://www.chuv.ch/fileadmin/sites/dedop/52184_21_fiche_endocrinologie_pediatrique__1_.pdf','Traitement de la puberté précoce','CHUV Suisse','2021','chuv-treatment.pdf','Trois pages : début pubertaire, traitement, injection, soutien et effets indésirables','Parents et enfants traités','Brochure ancienne : formulations et intervalle Lucrin non transférés au 3,75 mg mensuel. Les phrases rassurantes sur absence de risque/interactions sont confrontées aux FI, non adoptées. Pas remboursement 2026 garanti.','Avant huit ans chez la fille/neuf ans chez le garçon ; information adaptée, soutien et rendez-vous de suivi. Les FI actuelles décrivent des effets et précautions qui empêchent une rassurance générale.')
add('S5','https://pmc.ncbi.nlm.nih.gov/articles/PMC9066594/','Pubertal induction and transition to adult sex hormone replacement: Endo-ERN clinical practice guideline','Nordenström et coll., Endo-ERN ; recommandations européennes ESPE/ESE/EAA','2022','endoern2022.html','Physiologie/minipuberté ; biologie ; R1.1, R2.1–2.11 ciblées, R3.1–3.9, R4.1–4.2 et rationales ; tableaux ciblés','Déficits hypophysaires/gonadiques, enfants et transition','Sections réellement lues, pas totalité du texte/tableaux ; nombreuses preuves faibles et données issues de Turner. Doses de protocole ne deviennent pas une FI suisse.','Évaluer absence de seins à treize ans et de croissance testiculaire à quatorze ; suivi plus tôt si risque connu. Induction progressive, individualisée, estradiol ou testostérone ; gonadotropines discutées pour hypogonadisme central/fertilité. Testostérone seule n’induit pas croissance testiculaire et spermatogenèse.')
add('S6','https://pmc.ncbi.nlm.nih.gov/articles/PMC11729124/','Management of andrological disorders from childhood and adolescence to transition age: SIAMS/SIEDP part 1','Bonomi et coll., sociétés italiennes','En ligne 2024, volume 2025','siams2024.html','Sections puberté précoce/retardée, recommandations R5–R6 ; diagnostics et traitements ciblés','Garçons, adolescence et transition','Guideline européenne masculine, pas extrapolée à toutes les filles ; plages et forces de preuve conservées. Imagerie confrontée à revue européenne 2026.','L’examen et le tempo guident profil et imagerie. Une hormone lutéinisante basse n’exclut pas un début central. Le test dynamique ne distingue pas seul retard constitutionnel et déficit congénital. Traiter causes fonctionnelles et suivre le risque permanent.')
add('S7','https://paediatri.dk/images/dokumenter/Retningslinjer_2025/Pubertas_pr%C3%A6cox_febr._2025.pdf','Pubertas præcox hos piger og drenge','Danish Paediatric Society, Europe','Approuvée février 2025','dps2025.pdf','p.1–3 ; exploration et interprétation p.5–8 ; traitement/suivi p.9–10','Filles et garçons avec suspicion de précocité','Version approuvée trouvée sur le site DPS, distincte du projet 2024 non approuvé. Produits danois non attribués à FI suisse ; seuils/méthodes et âges osseux non universels.','Avant huit/neuf ans, distinguer central et périphérique, variantes et progression. Critères stimulés indicatifs et chevauchements à deux–trois ans. Filles moins de six ans et garçons : imagerie selon ce guide ; six–huit ans filles à discuter. Traitement individualisé, bénéfice de taille plus établi dans les débuts très précoces.')
add('S8','https://register.awmf.org/assets/guidelines/174-022l_S1_Pubertas-tarda-und-Hypogonadismus_2021-12.pdf','Pubertas tarda und Hypogonadismus','DGKED / AWMF Allemagne','Révision novembre 2021, réexamen prévu novembre 2026','awmf2021.pdf','Définition, signes, bilan, traitement et schémas ciblés','Enfants et adolescents avec retard','Recommandation S1 ancienne ; seuil féminin 13,5 ans et volume 3,5 ml distingués de Endo-ERN 13 ans/4 ml ; traitements allemands non assimilés aux produits suisses.','L’arrêt de progression plus de dix-huit mois mérite exploration. Anamnèse/examen, maladies chroniques et axe gonadotrope sont recherchés ; soutien et induction proportionnée selon cause, détresse et diagnostic.')
for i,k,pmid,note in [('S9','swiss-girls1983','6618891','142 filles de la première étude longitudinale zurichoise 1954–1980 ; ménarche moyenne 13,4 ±1 an, diversité du tempo ; donnée historique de développement normal, pas incidence actuelle des anomalies.'),('S10','swiss-boys1983','6618890','142 garçons de la première étude zurichoise 1954–1980 ; définition historique d’initiation à trois ml et durée variable, non seuil moderne universel.')]:
 j=json.loads((C/(k+'-meta.json')).read_text())['resultList']['result'][0]
 add(i,'https://pubmed.ncbi.nlm.nih.gov/'+pmid+'/',j['title'],'Largo et Prader, Suisse','1983',k+'-meta.json','Résumé publié','Cohorte suisse historique de 142 enfants par sexe','Résumé seul, cohortes 1954–1980 ; pas norme 2026 ni fréquence E30. Définitions historiques de puberté incluent signes différents.',note,'abstract')
fi=[('S11','Lucrin Dépôt 3,75 mg seringue double compartiment','7680519030489','Mai 2025','lucrin.txt','Puberté centrale rapidement progressive, critères de début et test ; dose 0,3 mg/kg/4 semaines minimum 7,5 mg, tableau 7,5/11,25/15 mg selon poids, paliers 3,75 mg si nécessaire. Pas la formulation douze semaines. Stop avant onze/douze ans selon sexe de la FI ; limites de produit distinctes des objectifs de protocole.'),('S12','Pamorelin LA 22,5 mg','7680612380023','Juillet 2026','pamorelin.txt','Dès deux ans, début avant huit/neuf ans ; 22,5 mg intramusculaire toutes les vingt-quatre semaines. Reconstitution avec 2 ml, contrôle hormonal après un–deux mois, taille tous trois–six mois. Réactions cutanées sévères, pseudotumeur cérébrale et humeur figurent parmi les précautions actuelles.'),('S13','Testoviron Dépôt 250 mg/ml','7680176260359','Juillet 2026','testoviron.txt','Induction tardive chez le garçon : début 50 mg toutes quatre semaines, progression jusqu’à 250 mg toutes trois semaines en trois ans. Injection huileuse intramusculaire lente et profonde ; expert pédiatrique, pas avant âge de la puberté ; absence d’études pédiatriques gardée explicite. Polyglobulie, interactions et risques d’injection.'),('S14','Progynova 2 mg et Progynova mite 1 mg','7680331490423','Octobre 2022','progynova.txt','La FI adulte ne prévoit aucune indication enfant/adolescente. Dose adulte 2 mg/j puis éventuellement 1 mg/j, non dose de début pubertaire ; contre-indications thromboemboliques, hépatiques et grossesse, progestatif si utérus en schéma adulte. Protocole européen pédiatrique séparé, pas recette de fractionnement.'),('S15','Testosteron-Mepha 1000 mg/4 ml','7680689890012','Juin 2026','testosteron-mepha.txt','Undécanoate huileux adulte 1000 mg toutes dix–quatorze semaines, intervalle initial éventuellement six semaines. Aucune étude sous dix-huit ans, pas de remplacement du schéma d’induction par énanthate ; micro-embolie à surveiller.')]
for i,title,gtin,version,file,note in fi:
 add(i,'https://amiko.oddb.org/fr/fi?gtin='+gtin,'Information professionnelle suisse '+title,'Swissmedic/AIPS via AmiKo',version,file,'Formulation, indication, posologie, contre-indications, précautions ; interactions et grossesse ciblées sauf S15 comparatif adulte limité','Produit exact, populations explicitées','Pas équivalence entre préparations ou entre FI et protocole. Maximum non inventé ; données adultes ne sont pas incidences pédiatriques.',note)
