add('S16','https://pubmed.ncbi.nlm.nih.gov/33687345/',j['title'],'Seppä et coll., European Journal of Endocrinology','2021','primary-amenorrhea-meta.json','Résumé publié, définition et mécanismes','Filles avec aménorrhée ou retard','Résumé seul, pas fondement de dose. Le délai post-thélarche a une exception si début avant dix ans ; aucune règle simplifiée universelle.','Absence de ménarche à quinze ans avec développement, ou treize ans sans signes, justifie enquête ; mécanismes centraux, gonadiques, endocriniens et utéro-vaginaux sont distingués.','abstract')
add('S17','https://pmc.ncbi.nlm.nih.gov/articles/PMC13422188/','Precocious puberty in boys: current insights into etiology, genetic advances, and environmental factors','Amodeo et coll., revue européenne italienne','2026','cpp2026.html','Résumé ; risque intracrânien, tableau de cohortes et limites de sélection ; génétique ciblée','Garçons avec forme centrale','Revue, pas nouveau consensus européen validé ; reprend guideline Endocrine Society américaine 2026 avec propositions à valider. Ni source américaine seule ni justification automatique de ne pas imager. Les cohortes récentes excluent certains risques.','Les séries récentes italiennes trouvent moins de lésions que les anciennes séries mélangées. Âge très jeune, progression et signes neurologiques restent prioritaires. Stratégie sélective discutée face aux guides 2025 ; variants MKRN3/DLK1 à expression paternelle et KISS1/KISS1R selon mécanisme.')
for i,k,title,url,note in [('S18','openstax-male','Anatomy and physiology of the testicular reproductive system','27-1-anatomy-and-physiology-of-the-testicular-reproductive-system','Testicule, enveloppes, lobules, tubules, cellules de Sertoli et Leydig et contrôle gonadotrope. Ne pas reprendre la simplification qui fait de la baisse de FSH par inhibine une baisse directe de testostérone.'),('S19','openstax-female','Anatomy and physiology of the ovarian reproductive system','27-2-anatomy-and-physiology-of-the-ovarian-reproductive-system','Ovaires pelviens, follicules et granulosa/thèque ; croissance folliculaire et stéroïdes, structures utéro-vaginales. Les descriptions normales ne sont pas un examen diagnostique individuel.')]:
 add(i,'https://openstax.org/books/anatomy-and-physiology-2e/pages/'+url,title,'OpenStax','2e, chapitre 27, version servie 2026',k+'.html','Anatomie, cellules, hormones et rétrocontrôle ciblés','Science normale','Manuel pédagogique américain, pas recommandation clinique ; paraphrases ciblées, aucun conseil américain de traitement comme fondement. Licence propre aux figures distincte du site actuel.',note)
add('S20','https://smifk-cims.ch/download_file/view/c28daec4-78b0-4a6e-a198-00ca757191fc/261','PROFILES','CIMS Suisse','2017','/workspace/medina-source-cache/C85/profiles2017-official.pdf','Situations organes génitaux, croissance/puberte, pression ; passages déjà réellement lus ce jour','Formation médicale suisse','Réutilisation déclarée d’une lecture du jour ; correspondance pédagogique non officielle, aucune question garantie.','Le raisonnement s’applique à croissance/puberte inhabituelles et examen génital proportionné ; la liste n’est pas une classification CIM officielle.')
add('S21','https://pmc.ncbi.nlm.nih.gov/articles/PMC7550972/','Trends in the incidence of central precocious puberty and normal variant puberty in Denmark, 1998–2017','Bräuner et coll., cohorte danoise ; JAMA Network Open','2020','denmark2020.html','Résumé, résultats et Strengths and Limitations','Registre danois, 8596 enfants avec trois groupes diagnostiques','Éditeur américain mais cohorte européenne descriptive, pas recommandation de traitement. Codes non validés sur chaque dossier, possible non-confirmation ou adressements croissants ; pas incidence suisse ni E30 entière.','Parmi les enfants d’origine danoise définie par registre, moyenne annuelle 9,2/10000 filles et 0,9/10000 garçons pour diagnostic central 1998–2017 ; pas chiffre de toute la population suisse. Les 8596 cas incluent thélarche/adrenarche, pas seulement forme centrale.')
P=D/'recherche_E30';P.mkdir(exist_ok=True);out=json.dumps({'sources':rows},ensure_ascii=False,indent=2)+'\n';(P/'sources.json').write_text(out);(D/'source-ledger.json').write_text(out)
labels=['Question clinique et examen','Définition et périmètre','Classification','Épidémiologie suisse puis Europe','Normal puis pathologique','Étiologies et risques','Anamnèse','Examen clinique','Urgences','Explorations','Différentiels','Traitement suisse et FI','Complications et pronostic','Suivi et prévention','Populations particulières','Aspects administratifs suisses','Critères formels','Paramètres chiffrés','Sous-codes','Objectifs et pièges']
ss=['S20 S3','S1 S2 S5','S1 S2 S5 S7','S9 S10 S21','S5 S18 S19','S5 S6 S7 S17','S3 S5 S7','S3 S5 S7','S7 S12 S13 S17','S5 S6 S7','S5 S6 S7 S16','S5 S11 S12 S13 S14 S15','S5 S6 S7','S3 S5 S7','S5 S11 S12 S13 S14','S1 S2 S4','S5 S7 S8 S16','S5 S11 S12 S13','S1 S2','S20 S5 S7']
t='# Recherche E30 — Anomalies de la puberté\n\nLecteur sol_endocrinologie, 2 novembre 2026. Sources réellement lues aux sections déclarées. E30.0, E30.1, E30.8 et E30.9 distingués ; forme centrale E22.8 expliquée comme exclusion, pas modification de cette autre leçon.\n\n## Matrice de complétude\n\n| rubrique | statut | sources |\n|---|---|---|\n'
for n,(l,s) in enumerate(zip(labels,ss),1):t+=f'| {n}. {l} | ✔ | '+', '.join('['+i+']' for i in s.split())+' ; limites des lectures explicitées ci-dessous. |\n'
t+='\n## Arbitrages avant rédaction\n\nLe PDF danois 2024 est un projet avec approbation vide ; il ne fonde pas les décisions. La version approuvée février 2025 a été retrouvée sur le site de la société et lue. La brochure CHUV 2021 ne prouve ni absence d’effets indésirables ni absence d’interactions, ni remboursement 2026. La FI Lucrin 3,75 mg mensuelle ne devient pas la formulation douze semaines. Les critères de traitement et limites d’arrêt des FI se distinguent des seuils de diagnostic et de l’âge osseux des guides. La FI Lucrin mentionne un scanner ; les recommandations cliniques discutent IRM et indications actualisées : pas imagerie irradiant automatique. Les guides européens 2025 imagent tous les garçons centraux ; la revue européenne 2026 discute une stratégie plus sélective à valider, sur cohortes sélectionnées et guideline américaine ; conserver ce désaccord sans exclure la lésion sur antécédents familiaux seuls.\n\n13 ans et 4 ml dans Endo-ERN ne sont pas les mêmes seuils que 13,5 ans/3,5 ml AWMF ni trois ml historiques suisses ; méthode, âge, progression et source gardent leur place. Un test dynamique ne sépare pas seul retard constitutionnel et déficit permanent. L’induction chez la fille n’est pas une prescription pédiatrique autorisée par la FI Progynova adulte ; pas recette de découpe. Testoviron a une rubrique d’induction tardive, mais pas indication avant âge pubertaire ni preuve d’étude pédiatrique à inventer. L’undécanoate adulte ne remplace pas une faible dose d’énanthate au début. Pubarche et thélarche ne prouvent pas seules la même activation.\n\n## Sources et limites réelles\n\n'
for s in rows:t+=f"### [{s['id']}] {s['titre']}\n\n{s['section_page']}. {s['passage_paraphrase']} Population : {s['population']}. Limites : {s['limites']}\n\n"
(P/'recherche.md').write_text(t)
(D/'source-cache-manifest.json').write_text(json.dumps(dict(at=datetime.datetime.now(datetime.timezone.utc).isoformat(),full_sources_outside_git=True,sources=[dict(id=s['id'],path=s['cache_external'],sha256=s['sha256'],read_level=s['read_level']) for s in rows]),ensure_ascii=False,indent=2)+'\n')
print(len(rows),'sources réellement consultées, niveaux déclarés')
